import fs from 'node:fs';
import path from 'node:path';
import { collectExtensionFiles, extensionZip, projectRoot, sourcePackageFiles } from './extension-package.mjs';

const { manifest, files } = collectExtensionFiles(path.join(projectRoot, 'extension'));
if (!/^\d+\.\d+\.\d+(?:\.\d+)?$/.test(manifest.version || '')) throw Error('Invalid extension version');
const dist = path.resolve(projectRoot, 'dist');
const label = 'boss-helper-edge-' + manifest.version;
const directory = path.resolve(dist, label);
// This directory is generated by this script. Never remove a user-selected path.
if (path.dirname(directory) !== dist || !path.basename(directory).startsWith('boss-helper-edge-')) throw Error('Invalid build target');
fs.mkdirSync(dist, { recursive: true });
if (fs.existsSync(directory)) fs.rmSync(directory, { recursive: true });
fs.mkdirSync(directory, { recursive: true });
for (const [name, bytes] of files) {
  const target = path.join(directory, name);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, bytes);
}
const archive = path.join(dist, label + '.zip');
const sourceArchive = path.join(dist, label + '-github.zip');
fs.writeFileSync(archive, extensionZip(files));
fs.writeFileSync(sourceArchive, extensionZip(sourcePackageFiles(projectRoot, files)));
console.log(`Extension ${manifest.version}: ${files.size} runtime files`);
console.log(`Load unpacked: ${directory}`);
console.log(`Extension ZIP: ${archive}`);
console.log(`GitHub source ZIP: ${sourceArchive}`);
